with rows as (select * from jsonb_to_recordset('[{"title":"2030 · Reproduce evidence-first LP notebook","status":"Complete","evidence":"2026-11-19: notebook executed locally; SciPy HiGHS optimal; 12/12 numerical checks passed. This verifies reproducibility of the scenario only; underlying source assumptions are not fully validated. https://github.com/aayush-bhatta/nepal-gep-workspace/blob/main/research/2030/Nepal_GEP_2030_Complete_Evidence_First.ipynb","next_action":"Retain output CSV and rerun after input audit."},{"title":"2030 · Verify 1,077.481 MW unclassified hydro and 904.600 MW IPP labels","status":"In progress","evidence":"Notebook capacity reconciliation preserves unknown categories; assignment as ROR-like is an explicit unverified assumption.","next_action":"Cross-check individual operating schemes, capacity totals, and plant commissioning with NEA/DoED source tables."},{"title":"2030 · Validate hourly demand, ROR/PROR inflows and solar time series","status":"Not started","evidence":"Notebook uses synthetic demand and 2040 hydrology proxies; PV has diurnal sine curve and 17% annual CF.","next_action":"Obtain original hourly NEA demand, measured hydro/PROR inflow and validated multi-site PV output."},{"title":"2030 · Audit cost benchmarks, import assumptions and commissioning ceilings","status":"Not started","evidence":"2026-11-19 rerun used embedded planning cost benchmarks, 145 NPR/USD, 8% WACC, 750 MW import limit and illustrative 2030 capacity caps.","next_action":"Cross-validate CAPEX/O&M, 2030 COD, USD/NPR exchange rate, PPA/procurement and import/export market assumptions."},{"title":"2030 · Run source-sensitive scenario analyses","status":"Not started","evidence":"Only one illustrative baseline LP run completed. No sensitivity results have been calculated or published.","next_action":"Vary unclassified hydro assignment, solar CF, FX/discount, capacity ceilings and import prices; compare capacity and energy mixes."},{"title":"2030 · Upgrade chronology, network and stochastic reliability","status":"Not started","evidence":"Model optimizes 288 representative hourly states, reconstructs 8760 recurring profiles; deterministic ENS only.","next_action":"Use true 8760 varied profiles, transmission transfer constraints and outages for EENS/LOLE before research-grade conclusions."}]'::jsonb) as x(title text,status text,evidence text,next_action text))
insert into public.tasks(title,status,evidence,next_action)
select x.title,x.status,x.evidence,x.next_action from rows x
where not exists(select 1 from public.tasks t where t.title=x.title);
with rows as (select * from jsonb_to_recordset('[{"title":"2030 · Unknown hydro allocation to ROR","parameter":"Unclassified hydro dispatched as ROR-like","baseline_value":"100% of 1,077.481 MW","unit":"fraction","justification":"Major national plant classification gap; baseline intentionally assumes no additional peaking flexibility.","next_action":"Test alternative allocation after evidence audit; do not claim modelled response before a rerun."},{"title":"2030 · Solar PV annual capacity factor","parameter":"Solar annual CF","baseline_value":"0.17","unit":"fraction","justification":"Synthetic 12×24 solar profile currently calibrated to 17%; site-level resource not verified.","next_action":"Use source-backed hourly PV data and compare capacity/energy outcomes."},{"title":"2030 · Import capacity and historical price","parameter":"Import limit and price","baseline_value":"750 MW and ~9.018 NPR/kWh","unit":"MW and NPR/kWh","justification":"Both are historical/planning proxies; import cap binds in February representative day.","next_action":"Test alternative signed trade/price cases with documented assumptions."},{"title":"2030 · CAPEX and financial assumptions","parameter":"Technology CAPEX, 8% discount, 145 NPR/USD","baseline_value":"Embedded cost rows; 0.08 discount; NPR 145 per USD","unit":"scenario parameters","justification":"External CSV was not mounted in the local rerun and financial assumptions are provisional.","next_action":"Load independently verified costs and test plausible bounds."}]'::jsonb) as x(title text,parameter text,baseline_value text,unit text,justification text,next_action text))
insert into public.sensitivities(title,horizon,baseline_run_id,parameter,baseline_value,sensitivity_value,unit,justification,model_version,status,results,issues,next_action)
select x.title,2030,(select id from public.model_runs where model_version='2030-evidence-first-notebook-v1' limit 1),x.parameter,x.baseline_value,null,x.unit,x.justification,'2030-evidence-first-notebook-v1','Not run',null,
'No sensitivity experiment has been executed.',x.next_action from rows x
